export interface Envelope {
  id: string;
  payload: unknown;
}

type AnyOf<T> = T[keyof T];
const anyMatch = (xs: readonly string[]): boolean => xs.some(Boolean);

export function decode(raw: string): Envelope {
  const parsed: unknown = JSON.parse(raw);
  if (typeof parsed !== 'object' || parsed === null) throw new TypeError('not an envelope');
  const headers: Record<string, unknown> = 'headers' in parsed ? (parsed.headers as Record<string, unknown>) : {};
  const id: AnyOf<{ id: string }> = String(headers['id']);
  return anyMatch([id]) ? { id, payload: parsed } : { id: '', payload: null };
}

